if __name__ == "__main__":
    from papers_msdefs import book_gloss
    path = os.path.join(ROOT, "papers", "mswording.json")
    W = json.load(open(path, encoding="utf-8"))
    bad = 0
    for book, rows in ADD.items():
        gl = {g["term"].lower(): g["term"] for g in book_gloss(book)}
        dst = W.setdefault(book, {})
        for term, ref, marks, q, ms in rows:
            t = gl.get(term.lower())
            if not t:
                print("NOT IN GLOSSARY", book, term); bad += 1; continue
            for k in [k for k in dst if k.lower() == t.lower()]:
                del dst[k]
            dst[t] = {"ms": ms, "ref": ref, "qtext": q, "marks": marks}
        W[book] = dict(sorted(dst.items(), key=lambda kv: kv[0].lower()))
    json.dump(W, open(path, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print({b: len(v) for b, v in W.items()}, "missing:", bad)
